window.addEventListener('error',function(e){try{var t=document.getElementById('toast');if(t){t.textContent='⚠️ App error: '+(e.message||'unknown');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),4000)}console.error('Ilmora error:',e.error||e.message)}catch(_){}});
const state={surahs:[],timings:null,audio:null,bookmarks:JSON.parse(localStorage.getItem('ilmora_bookmarks')||'[]'),tasbeeh:+localStorage.getItem('ilmora_tasbeeh')||0,lastRead:JSON.parse(localStorage.getItem('ilmora_lastread')||'null'),theme:localStorage.getItem('ilmora_theme')||'light',orders:JSON.parse(localStorage.getItem('ilmora_orders')||'[]'),adhanOn:localStorage.getItem('ilmora_adhan')!=='0',adhanFired:{},adhanDate:null};
const ADHAN_URL='https://cdn.aladhan.com/audio/adhans/a9.mp3';
const prayers=['Fajr','Dhuhr','Asr','Maghrib','Isha'];
const $=id=>document.getElementById(id);
function toast(m){$('toast').textContent=m;$('toast').classList.add('show');clearTimeout(window.__t);window.__t=setTimeout(()=>$('toast').classList.remove('show'),1900)}
function save(){localStorage.setItem('ilmora_bookmarks',JSON.stringify(state.bookmarks));localStorage.setItem('ilmora_tasbeeh',state.tasbeeh);localStorage.setItem('ilmora_lastread',JSON.stringify(state.lastRead));updateStats()}
function openModal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('moduleModal').classList.add('show');$('moduleModal').setAttribute('aria-hidden','false')}
function closeModal(){$('moduleModal').classList.remove('show');$('moduleModal').setAttribute('aria-hidden','true')}
function openSettings(){$('settingsModal').classList.add('show')}
function closeSettings(){$('settingsModal').classList.remove('show')}
function applyTheme(){document.documentElement.dataset.theme=state.theme;const dark=state.theme==='dark';document.documentElement.style.setProperty('--bg',dark?'#081713':'#f6f4ec');document.documentElement.style.setProperty('--panel',dark?'#102420':'#fff');document.documentElement.style.setProperty('--panel-tint',dark?'#0e211d':'#fbfaf3');document.documentElement.style.setProperty('--pearl',dark?'#132a24':'#faf8f1');document.documentElement.style.setProperty('--ink',dark?'#eef4ef':'#182420');document.documentElement.style.setProperty('--muted',dark?'#93a89d':'#6f7d74');document.documentElement.style.setProperty('--line',dark?'#1e3a32':'#e7e1d0');document.documentElement.style.setProperty('--soft',dark?'#152e27':'#eef3ee');$('themeToggle').textContent=dark?'Light':'Dark';localStorage.setItem('ilmora_theme',state.theme)}
$('themeToggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';applyTheme()}
function updateAdhanToggle(){$('adhanToggle').textContent=state.adhanOn?'On':'Off'}
$('adhanToggle').onclick=()=>{state.adhanOn=!state.adhanOn;localStorage.setItem('ilmora_adhan',state.adhanOn?'1':'0');updateAdhanToggle();toast(state.adhanOn?'🕌 Adhan alerts turned on':'Adhan alerts turned off');if(state.adhanOn&&'Notification' in window&&Notification.permission==='default'){Notification.requestPermission().catch(()=>{})}}
updateAdhanToggle();
function playAdhan(name){if(state.audio){state.audio.pause()}const a=new Audio(ADHAN_URL);state.audio=a;$('track').textContent=name+' • Adhan';$('mini').classList.add('show');$('play').onclick=()=>a.paused?a.play():a.pause();$('closeAudio').onclick=()=>{a.pause();$('mini').classList.remove('show')};a.onplay=()=>{$('play').textContent='Ⅱ'};a.onpause=()=>{$('play').textContent='▶'};a.onended=()=>{$('mini').classList.remove('show')};a.play().catch(()=>toast('Tap ▶ in the player to hear the '+name+' Adhan'));toast('🕌 It\'s time for '+name);if('Notification' in window&&Notification.permission==='granted'){try{new Notification('Ilmora — '+name,{body:"It's time for "+name+' prayer.'})}catch(e){}}}
function checkAdhan(now){if(!state.timings||!state.adhanOn)return;const key=now.toDateString();if(state.adhanDate!==key){state.adhanDate=key;state.adhanFired={}}prayers.forEach(n=>{const t=state.timings[n];if(!t)return;const [h,m]=t.split(':').map(Number);if(now.getHours()===h&&now.getMinutes()===m&&!state.adhanFired[n]){state.adhanFired[n]=true;playAdhan(n)}})}
function clearLocalData(){if(confirm('Reset Ilmora local progress?')){localStorage.removeItem('ilmora_bookmarks');localStorage.removeItem('ilmora_tasbeeh');localStorage.removeItem('ilmora_lastread');location.reload()}}
function openDuas(){openModal('Duas & Azkar',`<div class="choice"><button onclick="showDua('Morning Azkar','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ','We have entered the morning and the dominion belongs to Allah.')"><b>Morning Azkar</b><small>Start your day with remembrance</small></button><button onclick="showDua('Evening Azkar','أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ','We have entered the evening and the dominion belongs to Allah.')"><b>Evening Azkar</b><small>End your day with remembrance</small></button><button onclick="showDua('Forgiveness','أَسْتَغْفِرُ اللَّهَ','I seek forgiveness from Allah.')"><b>Istighfar</b><small>Simple daily dhikr</small></button><button onclick="showDua('Salawat','اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ','O Allah, send blessings upon Muhammad ﷺ.')"><b>Salawat</b><small>Send blessings upon the Prophet ﷺ</small></button></div>`)}
function showDua(title,ar,en){openModal(title,`<div class="card"><div class="dhikr">${ar}</div><p style="text-align:center;color:var(--muted);line-height:1.7">${en}</p><div class="rowbtn"><button class="pill" onclick="speakText(${JSON.stringify(ar)})">🔊 Listen</button><button class="pill" onclick="shareText(${JSON.stringify(ar+' — '+en)})">↗ Share</button></div></div>`)}
function speakText(t){if('speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ar-SA';speechSynthesis.speak(u)}else toast('Speech is not supported on this device')}
const hadiths=[{ar:'إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ',en:'Actions are judged by intentions.',hi:'कर्मों का दारोमदार नीयतों पर है।',ref:'Sahih al-Bukhari 1'},{ar:'مَنْ لَا يَرْحَمُ لَا يُرْحَمُ',en:'Whoever does not show mercy will not be shown mercy.',hi:'जो दया नहीं करता, उस पर दया नहीं की जाती।',ref:'Sahih al-Bukhari 7376'},{ar:'خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ',en:'The best of you are those who learn the Quran and teach it.',hi:'तुम में सबसे बेहतर वह है जो कुरआन सीखे और सिखाए।',ref:'Sahih al-Bukhari 5027'},{ar:'الطُّهُورُ شَطْرُ الإِيمَانِ',en:'Purification is half of faith.',hi:'पवित्रता ईमान का आधा हिस्सा है।',ref:'Sahih Muslim 223'}];function openHadith(){const h=hadithData[Math.floor(Date.now()/86400000)%hadithData.length];openModal('Daily Hadith',`<div class="card"><div class="ayah-ar">${h.ar}</div><div class="translation"><b>English:</b> ${h.en}</div><div class="translation"><b>हिन्दी:</b> ${h.hi}</div><div class="ref">${h.ref}</div><div class="rowbtn"><button class="pill" onclick="shareText(${JSON.stringify(h.en+' — '+h.ref)})">↗ Share</button><button class="pill" onclick="closeModal()">Done</button></div></div>`)}
function openCalendar(){const d=new Date();const islamic=new Intl.DateTimeFormat('en-TN-u-ca-islamic',{day:'numeric',month:'long',year:'numeric'}).format(d);openModal('Hijri Calendar',`<div class="card" style="text-align:center"><div class="eyebrow">TODAY</div><div class="hijri" style="font-size:30px;margin:12px 0">${islamic}</div><div>${d.toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><p style="color:var(--muted);font-size:11px">Hijri date is calculated by the device calendar and may differ from local moon-sighting authorities.</p></div>`)}
function openZakat(){openModal('Zakat Calculator',`<p style="color:var(--muted);font-size:11px;margin-bottom:10px">Enter the current value of everything you have owned for a full lunar year. Zakat is 2.5% of the total, if it is above the Nisab threshold.</p><input id="zCash" class="field" type="number" placeholder="Cash & bank balance (₹)"><input id="zGold" class="field" type="number" placeholder="Gold & silver value (₹)"><input id="zBiz" class="field" type="number" placeholder="Business stock / investments (₹)"><input id="zDebt" class="field" type="number" placeholder="Debts you owe to others (₹)"><button class="counter-btn" onclick="calcZakat()">Calculate Zakat</button><div id="zResult" style="margin-top:12px"></div><p style="color:var(--muted);font-size:10px;margin-top:10px;text-align:center">This is a simplified estimate. Please consult a knowledgeable scholar for your exact Nisab and specific assets.</p>`)}
function calcZakat(){const n=id=>Number($(id).value)||0;const total=n('zCash')+n('zGold')+n('zBiz')-n('zDebt');const zakat=total>0?total*0.025:0;$('zResult').innerHTML=`<div class="orow"><span>Net Zakatable Wealth</span><b>₹${total.toLocaleString('en-IN')}</b></div><div class="orow"><span>Zakat Due (2.5%)</span><b style="color:var(--teal)">₹${zakat.toLocaleString('en-IN',{maximumFractionDigits:0})}</b></div>`}
function openQibla(){openModal('Qibla Direction',`<div class="degree" id="qiblaDegree">Requesting location…</div><div class="qibla-compass"><div class="needle" id="qiblaNeedle">🧭</div></div><p id="qiblaInfo" style="text-align:center;color:var(--muted);font-size:11px">Allow location access to calculate the direction to the Kaaba.</p>`);navigator.geolocation?.getCurrentPosition(p=>{const b=bearing(p.coords.latitude,p.coords.longitude,21.4225,39.8262);$('qiblaDegree').textContent=Math.round(b)+'° from true north';$('qiblaNeedle').style.transform=`rotate(${b}deg)`;$('qiblaInfo').textContent='Approximate Qibla bearing from your current location.'},()=>{$('qiblaInfo').textContent='Location permission was not granted.'})}
function bearing(lat1,lon1,lat2,lon2){const r=Math.PI/180,a1=lat1*r,a2=lat2*r,d=(lon2-lon1)*r;return (Math.atan2(Math.sin(d)*Math.cos(a2),Math.cos(a1)*Math.sin(a2)-Math.sin(a1)*Math.cos(a2)*Math.cos(d))/r+360)%360}
$('bookmarkBtn').onclick=()=>openModal('Saved Ayahs',state.bookmarks.length?state.bookmarks.map(x=>`<div class="timing"><b>Quran ${x}</b><button class="pill" onclick="openSurah(${x.split(':')[0]});closeModal()">Open</button></div>`).join(''):'<div class="empty">No saved ayahs yet. Save ayahs from the Quran reader.</div>')
function updateStats(){$('tasCount').textContent=state.tasbeeh;$('bmCount').textContent=state.bookmarks.length}
function showScreen(id){document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.screen===id));window.scrollTo({top:0,behavior:'smooth'});if(id==='quran')loadSurahs();if(id==='hadith')renderHadith();if(id==='prayer'&&!state.timings)getLocation();if(id==='sadaqah'){renderPackages();renderOrders();renderStudents();renderParaGrid();syncParaStatusFromCloud()}if(id==='digitalStore'){renderDigitalStore();renderDigitalOrders()}if(id==='studentLogin')fillStudentSelect();if(id==='studentDashboard')renderStudentDashboard();if(id==='adminDashboard')renderAdminDashboard();if(id==='teacherDashboard')renderTeacherDashboard();if(id==='studentPortal')renderStudentPortal();if(id==='roleLogin'){const e=$('loginError');if(e)e.textContent=''}}
function renderStudentPortal(){
  if(!state.roleUser||state.roleUser.role!=='student'){showScreen('roleLogin');return}
  $('studentPortalName').textContent=state.roleUser.name||'Student';
  window.__fsListAssignmentsByStudent(state.roleUser.uid).then(list=>{
    const el=$('studentPortalList');
    el.innerHTML=list.length?list.map(a=>`<div class="stu" style="margin-bottom:8px"><div class="info"><b>Para ${a.paraNumber}</b><small>Status: ${a.status}</small></div>${a.status!=='completed'?`<button class="pill" onclick="studentMarkComplete('${a.id}')">Mark done</button>`:''}</div>`).join(''):'<div class="empty">No Para assigned yet — ask your teacher.</div>'
  }).catch(()=>{$('studentPortalList').innerHTML='<div class="empty">Could not load your Para.</div>'})
}
function studentMarkComplete(id){window.__fsUpdateAssignmentStatus(id,'completed').then(()=>{toast('Marked complete ✓');renderStudentPortal()}).catch(e=>toast('⚠️ '+e.message))}

/* ---------- Madrasa Students & Para Availability ---------- */
function updateCloudStatus(){var el=$('cloudStatus');if(!el)return;if(window.__fsReady){el.textContent='🟢 Cloud connected — orders will sync live';el.style.color='#0f766e'}else{el.textContent='🟠 Offline mode — orders save on this device only';el.style.color='#b45309'}}
setTimeout(updateCloudStatus,1200);
setTimeout(updateCloudStatus,3000);
const DEFAULT_STUDENTS=[
 {id:'s1',name:'Md. Ahmad Raza',age:11,range:[1,3],pin:'7462'},
 {id:'s2',name:'Bilal Hussain',age:12,range:[4,6],pin:'3819'},
 {id:'s3',name:'Zaid Ansari',age:10,range:[7,9],pin:'5207'},
 {id:'s4',name:'Md. Irfan',age:13,range:[10,12],pin:'9134'},
 {id:'s5',name:'Sohail Ahmed',age:11,range:[13,15],pin:'2680'},
 {id:'s6',name:'Md. Kaif',age:12,range:[16,18],pin:'6053'},
 {id:'s7',name:'Faizan Khan',age:10,range:[19,21],pin:'8371'},
 {id:'s8',name:'Md. Sameer',age:13,range:[22,24],pin:'4926'},
 {id:'s9',name:'Arbaz Alam',age:11,range:[25,27],pin:'1745'},
 {id:'s10',name:'Md. Yasin',age:12,range:[28,30],pin:'6398'}
];
state.customStudents=JSON.parse(localStorage.getItem('ilmora_customstudents')||'[]');
state.removedStudentIds=JSON.parse(localStorage.getItem('ilmora_removedstudents')||'[]');
function getAllStudents(){return [...DEFAULT_STUDENTS.filter(s=>!state.removedStudentIds.includes(s.id)),...state.customStudents]}
function saveStudentLists(){localStorage.setItem('ilmora_customstudents',JSON.stringify(state.customStudents));localStorage.setItem('ilmora_removedstudents',JSON.stringify(state.removedStudentIds))}
state.studentNames=JSON.parse(localStorage.getItem('ilmora_studentnames')||'{}');
function getStudentName(s){return (state.studentNames&&state.studentNames[s.id])||s.name}
state.studentPins=JSON.parse(localStorage.getItem('ilmora_studentpins')||'{}');
function getStudentPin(s){return (state.studentPins&&state.studentPins[s.id])||s.pin}
function studentForPara(n){return getAllStudents().find(s=>n>=s.range[0]&&n<=s.range[1])}
state.paraStatus=JSON.parse(localStorage.getItem('ilmora_parastatus')||'null')||(()=>{const o={};for(let i=1;i<=30;i++)o[i]={status:'available',completed:false};return o})();
function saveParaStatus(){localStorage.setItem('ilmora_parastatus',JSON.stringify(state.paraStatus))}
function availableParas(){return Object.keys(state.paraStatus).map(Number).filter(n=>state.paraStatus[n].status==='available').sort((a,b)=>a-b)}
function bookParas(nums,name,orderId){nums.forEach(n=>{state.paraStatus[n]={status:'booked',bookedBy:name,orderId};if(window.__fsSetPara)window.__fsSetPara(n,{num:n,status:'booked',bookedBy:name,orderId})});saveParaStatus()}
function renderParaGrid(){const el=$('paraGrid');if(!el)return;el.innerHTML=Array.from({length:30},(_,i)=>i+1).map(n=>{const st=state.paraStatus[n];let cls='avail',label=n,title=`Para ${n} — tap to sponsor`;if(st.status==='booked'){if(st.completed){cls='booked';label='✓';title=`Para ${n} — completed by student`}else{cls='booked';label='◔';title=`Para ${n} — sponsored, recitation in progress`}}return `<div class="pcell ${cls}" onclick="${st.status==='available'?`quickBookPara(${n})`:''}" title="${title}">${label}</div>`}).join('');
  const avail=availableParas().length,completed=Object.values(state.paraStatus).filter(s=>s.completed).length;
  $('paraStats').innerHTML=`<div><b>${completed}</b><span>Completed</span></div><div><b>${30-avail-completed}</b><span>In Progress</span></div><div><b>${avail}</b><span>Available</span></div>`;
}
function renderStudents(){const el=$('studentList');if(!el)return;const all=getAllStudents();if(!all.length){el.innerHTML='<div class="empty">No students added yet.</div>';return}el.innerHTML=all.map(s=>{const name=getStudentName(s);const total=s.range[1]-s.range[0]+1;const done=Array.from({length:total},(_,i)=>s.range[0]+i).filter(n=>state.paraStatus[n]&&state.paraStatus[n].completed).length;const pct=Math.round(done/total*100);return `<div class="stu"><div class="av">${name.split(' ').map(w=>w[0]).slice(0,2).join('')}</div><div class="info"><b>${name}</b><small>Para ${s.range[0]}–${s.range[1]} • Age ${s.age}</small><div class="bar"><i style="width:${pct}%"></i></div></div><div class="pct">${done}/${total}</div></div>`}).join('')}
function quickBookPara(n){openOrderForm('para1',n)}
function syncParaStatusFromCloud(){if(!window.__fsReady||!window.__fsLoadParaStatus)return;window.__fsLoadParaStatus().then(remote=>{if(!remote)return;let changed=false;Object.keys(remote).forEach(k=>{if(remote[k]&&remote[k].status){state.paraStatus[k]=remote[k];changed=true}});if(changed){saveParaStatus();renderParaGrid();renderStudents()}})}

/* ---------- Student Login & Dashboard ---------- */
state.currentStudent=JSON.parse(sessionStorage.getItem('ilmora_student')||'null');
function fillStudentSelect(){const sel=$('stuSelect');if(sel){sel.innerHTML=getAllStudents().map(s=>`<option value="${s.id}">${getStudentName(s)}</option>`).join('');sel.dataset.filled='1'}}
function attemptStudentLogin(){const id=$('stuSelect').value,pin=$('stuPin').value.trim();const s=getAllStudents().find(x=>x.id===id);if(!s){toast('Please select your name');return}if(pin!==getStudentPin(s)){toast('Incorrect PIN — please ask your teacher');return}state.currentStudent=s;sessionStorage.setItem('ilmora_student',JSON.stringify(s));showScreen('studentDashboard')}
function studentLogout(){state.currentStudent=null;sessionStorage.removeItem('ilmora_student');showScreen('profile')}

/* ---------- Admin Panel ---------- */
state.isAdmin=sessionStorage.getItem('ilmora_admin')==='1';

// ===== Real Firebase role-based auth (admin / teacher / student) =====
state.roleUser=null; // {uid,email,role,name,teacherUid?}
function attemptRoleLogin(){
  const email=$('loginEmail').value.trim(),pass=$('loginPass').value;
  const errEl=$('loginError');errEl.textContent='';
  if(!window.__auth){errEl.textContent='Connecting… please try again in a moment.';return}
  if(!email||!pass){errEl.textContent='Enter email and password.';return}
  window.__auth.signInWithEmailAndPassword(email,pass).then(cred=>{
    return window.__fsGetUserDoc(cred.user.uid).then(doc=>{
      if(!doc){errEl.textContent='No role found for this account.';window.__auth.signOut();return}
      state.roleUser=Object.assign({uid:cred.user.uid},doc);
      if(doc.role==='admin'){state.isAdmin=true;sessionStorage.setItem('ilmora_admin','1');showScreen('adminDashboard')}
      else if(doc.role==='teacher'){showScreen('teacherDashboard')}
      else if(doc.role==='student'){showScreen('studentPortal')}
      else{errEl.textContent='Unknown role for this account.'}
    })
  }).catch(e=>{errEl.textContent=e.message||'Login failed'})
}
function roleLogout(){if(window.__auth)window.__auth.signOut();state.roleUser=null;state.isAdmin=false;sessionStorage.removeItem('ilmora_admin');showScreen('home')}

function adminAddTeacher(){
  const name=$('newTeachName').value.trim(),email=$('newTeachEmail').value.trim(),pass=$('newTeachPass').value;
  if(!name||!email||pass.length<6){toast('Fill name, email, and a password (6+ chars)');return}
  if(!firebase.apps.length){toast('Not connected to Firebase');return}
  // Use a secondary app instance so creating the teacher doesn't log the admin out
  const secondary=firebase.apps.find(a=>a.name==='secondary')||firebase.initializeApp(firebase.app().options,'secondary');
  secondary.auth().createUserWithEmailAndPassword(email,pass).then(cred=>{
    return window.__fsCreateUserDoc(cred.user.uid,{email,name,role:'teacher'}).then(()=>secondary.auth().signOut())
  }).then(()=>{toast('Teacher added ✓');$('newTeachName').value='';$('newTeachEmail').value='';$('newTeachPass').value='';renderAdminTeacherList()}).catch(e=>toast('⚠️ '+e.message))
}
function renderAdminTeacherList(){
  const el=$('adminTeacherList');if(!el)return;
  window.__fsListTeachers().then(list=>{
    el.innerHTML=list.length?list.map(t=>`<div class="card" style="margin:8px 0;padding:12px"><b style="font-size:12px">${t.name||t.email}</b><small style="display:block;color:var(--muted)">${t.email}</small></div>`).join(''):'<div class="empty">No teachers yet.</div>'
  }).catch(()=>{el.innerHTML='<div class="empty">Could not load teachers.</div>'})
}

function teacherAddStudent(){
  const name=$('newTStuName').value.trim(),email=$('newTStuEmail').value.trim(),pass=$('newTStuPass').value;
  if(!name||!email||pass.length<6){toast('Fill name, email, and a password (6+ chars)');return}
  if(!state.roleUser){toast('Please log in again');return}
  const secondary=firebase.apps.find(a=>a.name==='secondary')||firebase.initializeApp(firebase.app().options,'secondary');
  secondary.auth().createUserWithEmailAndPassword(email,pass).then(cred=>{
    return window.__fsCreateUserDoc(cred.user.uid,{email,name,role:'student',teacherUid:state.roleUser.uid}).then(()=>secondary.auth().signOut())
  }).then(()=>{toast('Student added ✓');$('newTStuName').value='';$('newTStuEmail').value='';$('newTStuPass').value='';renderTeacherDashboard()}).catch(e=>toast('⚠️ '+e.message))
}
function renderTeacherDashboard(){
  if(!state.roleUser||state.roleUser.role!=='teacher'){showScreen('roleLogin');return}
  $('teacherName').textContent=state.roleUser.name||'Teacher';
  window.__fsListStudentsByTeacher(state.roleUser.uid).then(students=>{
    const listEl=$('teacherStudentList');
    listEl.innerHTML=students.length?students.map(s=>`<div class="card" style="margin:8px 0;padding:12px"><b style="font-size:12px">${s.name}</b><small style="display:block;color:var(--muted)">${s.email}</small></div>`).join(''):'<div class="empty">No students yet.</div>';
    const formEl=$('teacherAssignForm');
    if(!students.length){formEl.innerHTML='<div class="empty">Add a student first.</div>';return}
    formEl.innerHTML=`<select id="assignStuSelect" class="field">${students.map(s=>`<option value="${s.uid}">${s.name}</option>`).join('')}</select><input id="assignParaNum" class="field" type="number" min="1" max="30" placeholder="Para number (1-30)"><button class="counter-btn" onclick="teacherAssignPara()">Assign Para</button>`
  }).catch(()=>{$('teacherStudentList').innerHTML='<div class="empty">Could not load students.</div>'})
}
function teacherAssignPara(){
  const studentUid=$('assignStuSelect').value,para=Number($('assignParaNum').value);
  if(!para||para<1||para>30){toast('Enter a valid Para number (1-30)');return}
  window.__fsAddAssignment({studentUid,teacherUid:state.roleUser.uid,paraNumber:para}).then(()=>{toast('Para assigned ✓');$('assignParaNum').value=''}).catch(e=>toast('⚠️ '+e.message))
}
function adminLogout(){state.isAdmin=false;sessionStorage.removeItem('ilmora_admin');showScreen('profile')}
function renderAdminDashboard(){
  if(!state.isAdmin){showScreen('roleLogin');return}
  renderAdminTeacherList();
  const all=getAllStudents();
  // earnings summary
  const totalOrders=state.orders.length;
  const totalRevenue=state.orders.reduce((sum,o)=>sum+o.price,0);
  const totalMadrasa=state.orders.reduce((sum,o)=>sum+(o.madrasaShare||0),0);
  const totalAppFee=state.orders.reduce((sum,o)=>sum+(o.fee||0),0);
  $('adminEarnings').innerHTML=`<div><b>₹${totalRevenue}</b><span>Total Collected</span></div><div><b>₹${totalMadrasa}</b><span>To Madrasa</span></div><div><b>₹${totalAppFee}</b><span>App Fee</span></div>`;
  $('adminOrderCount').textContent=totalOrders+' order'+(totalOrders===1?'':'s')+' on this device';
  // students
  $('adminStudentList').innerHTML=all.map(s=>`<div class="card" style="margin:8px 0;padding:12px"><b style="font-size:12px">${getStudentName(s)}</b><small style="display:block;color:var(--muted);margin-bottom:8px">Para ${s.range[0]}–${s.range[1]} • Age ${s.age}</small><input id="adminName_${s.id}" class="field" style="margin-bottom:8px" value="${getStudentName(s)}" placeholder="Student name"><input id="adminPin_${s.id}" class="field" style="margin-bottom:8px" value="${getStudentPin(s)}" maxlength="4" inputmode="numeric" placeholder="4-digit PIN"><div class="rowbtn"><button class="pill" onclick="adminSaveStudent('${s.id}')">Save</button><button class="pill" style="background:#fde8e8;color:#b91c1c" onclick="adminRemoveStudent('${s.id}')">Remove</button></div></div>`).join('')||'<div class="empty">No students yet.</div>';
  // add new student form
  $('adminAddStudentForm').innerHTML=`<input id="newStuName" class="field" placeholder="Student name"><input id="newStuAge" class="field" type="number" placeholder="Age"><div style="display:flex;gap:8px"><input id="newStuFrom" class="field" type="number" min="1" max="30" placeholder="Para from"><input id="newStuTo" class="field" type="number" min="1" max="30" placeholder="Para to"></div><input id="newStuPin" class="field" maxlength="4" inputmode="numeric" placeholder="4-digit PIN"><button class="counter-btn" onclick="adminAddStudent()">+ Add Student</button>`;
  // orders with status control + delete
  const allOrders=state.orders.slice().reverse();
  $('adminOrderList').innerHTML=allOrders.length?allOrders.map((o)=>{const idx=state.orders.indexOf(o);return `<div class="card" style="margin:8px 0;padding:12px;${o.status&&o.status.includes('Verifying')?'border-color:#e0ad42':''}"><b style="font-size:12px">${o.pkg}</b><small style="display:block;color:var(--muted)">${o.name} • ${o.phone}</small>${o.paras&&o.paras.length?`<small style="display:block;color:var(--muted)">Para: ${o.paras.join(', ')}</small>`:''}${o.utr?`<div style="background:var(--soft);border-radius:8px;padding:6px 10px;margin:6px 0;font-size:12px"><b>UTR: ${o.utr}</b> — search this in your bank statement</div>`:''}<small style="display:block;color:var(--muted);margin-bottom:8px">${o.id} • ${new Date(o.date).toLocaleString()}</small><div class="orow" style="border:0;padding:4px 0"><span>Amount</span><b>₹${o.price}</b></div><select id="statusSel_${idx}" class="field" style="margin:6px 0"><option ${o.status==='Payment Pending — Verifying UTR'?'selected':''}>Payment Pending — Verifying UTR</option><option ${o.status==='Paid'?'selected':''}>Paid</option><option ${o.status==='Completed'?'selected':''}>Completed</option><option ${o.status==='UTR Not Found — Cancelled'?'selected':''}>UTR Not Found — Cancelled</option></select><div class="rowbtn"><button class="pill" onclick="adminUpdateOrderStatus(${idx})">Update Status</button><button class="pill" style="background:#fde8e8;color:#b91c1c" onclick="adminDeleteOrder(${idx})">Delete</button></div></div>`}).join(''):'<div class="empty">No orders yet on this device.</div>';
}
function adminSaveStudent(id){const name=$('adminName_'+id).value.trim();const pin=$('adminPin_'+id).value.trim();if(!name){toast('Name cannot be empty');return}if(!/^\d{4}$/.test(pin)){toast('PIN must be exactly 4 digits');return}state.studentNames[id]=name;state.studentPins[id]=pin;localStorage.setItem('ilmora_studentnames',JSON.stringify(state.studentNames));localStorage.setItem('ilmora_studentpins',JSON.stringify(state.studentPins));toast('Saved ✓');renderStudents()}
function adminRemoveStudent(id){if(!confirm('Remove this student? Their assigned Para will show as unassigned until reassigned.'))return;if(DEFAULT_STUDENTS.find(s=>s.id===id)){if(!state.removedStudentIds.includes(id))state.removedStudentIds.push(id)}else{state.customStudents=state.customStudents.filter(s=>s.id!==id)}saveStudentLists();renderAdminDashboard();renderStudents();toast('Student removed')}
function adminAddStudent(){const name=$('newStuName').value.trim(),age=Number($('newStuAge').value),from=Number($('newStuFrom').value),to=Number($('newStuTo').value),pin=$('newStuPin').value.trim();if(!name||!age||!from||!to||!/^\d{4}$/.test(pin)){toast('Please fill all fields correctly (PIN must be 4 digits)');return}if(from<1||to>30||from>to){toast('Para range must be between 1 and 30');return}const id='c'+Date.now();state.customStudents.push({id,name,age,range:[from,to],pin});saveStudentLists();renderAdminDashboard();renderStudents();toast('Student added ✓')}
function adminUpdateOrderStatus(idx){const sel=$('statusSel_'+idx);if(!sel||!state.orders[idx])return;const order=state.orders[idx];const newStatus=sel.value;
  if(newStatus==='UTR Not Found — Cancelled'&&order.status!==newStatus&&order.paras&&order.paras.length){
    order.paras.forEach(n=>{state.paraStatus[n]={status:'available',completed:false};if(window.__fsSetPara)window.__fsSetPara(n,{status:'available',completed:false,bookedBy:null,orderId:null})});
    saveParaStatus();renderParaGrid();renderStudents();
    toast('Para released back to available: '+order.paras.join(', '));
  }
  order.status=newStatus;localStorage.setItem('ilmora_orders',JSON.stringify(state.orders));if(window.__fsAdd)toast('Status updated locally (cloud order unaffected)');else toast('Status updated ✓');renderAdminDashboard()}
function adminDeleteOrder(idx){if(!confirm('Delete this order? This cannot be undone.'))return;state.orders.splice(idx,1);localStorage.setItem('ilmora_orders',JSON.stringify(state.orders));renderAdminDashboard();renderOrders();toast('Order deleted')}
function renderStudentDashboard(){const s=state.currentStudent;if(!s){showScreen('studentLogin');return}$('dashName').textContent=getStudentName(s);const total=s.range[1]-s.range[0]+1;const nums=Array.from({length:total},(_,i)=>s.range[0]+i);const done=nums.filter(n=>state.paraStatus[n]&&state.paraStatus[n].completed).length;const pending=nums.filter(n=>state.paraStatus[n]&&state.paraStatus[n].status==='booked'&&!state.paraStatus[n].completed).length;const free=nums.filter(n=>!state.paraStatus[n]||state.paraStatus[n].status==='available').length;
  $('dashStats').innerHTML=`<div><b>${done}</b><span>Completed</span></div><div><b>${pending}</b><span>To Recite</span></div><div><b>${free}</b><span>Not Sponsored</span></div>`;
  $('dashParaList').innerHTML=nums.map(n=>{const st=state.paraStatus[n]||{status:'available',completed:false};let statusLabel='Not yet sponsored',statusColor='var(--muted)',actionBtn='';
    if(st.status==='booked'&&!st.completed){statusLabel='Sponsored — ready to recite';statusColor='#b45309';actionBtn=`<button class="pill" onclick="markParaComplete(${n})">Mark Completed</button>`}
    else if(st.completed){statusLabel='Completed ✓';statusColor='#0f766e'}
    return `<div class="orow"><span>Para ${n}<br><small style="color:${statusColor}">${statusLabel}</small></span>${actionBtn}</div>`}).join('')}
function markParaComplete(n){const st=state.paraStatus[n];if(!st||st.status!=='booked'){toast('This Para is not yet sponsored');return}st.completed=true;saveParaStatus();if(window.__fsSetPara)window.__fsSetPara(n,{completed:true});toast('Para '+n+' marked as completed — Masha\'Allah! 🎉');renderStudentDashboard();renderParaGrid();renderStudents()}
/* ---------- Khatm-e-Quran Sadaqah ---------- */
const UPI_VPA='6207187995@axl'; // Punjab National Bank - 0890, primary account for receiving Isal-e-Sawab payments
const DIGITAL_FILE_MULK='data:application/pdf;base64,';
const DIGITAL_FILE_YASEEN='data:application/pdf;base64,';
const packages=[
 {id:'para1',title:'1 Para Sponsorship',desc:'Sponsor the recitation of 1 Para',price:49,paraCount:1},
 {id:'para5',title:'5 Para Sponsorship',desc:'Sponsor the recitation of 5 Para',price:149,paraCount:5},
 {id:'para10',title:'10 Para Sponsorship',desc:'Sponsor the recitation of 10 Para',price:249,paraCount:10},
 {id:'para15',title:'15 Para Sponsorship',desc:'15 Para (Half the Quran)',price:300,paraCount:15},
 {id:'khatm',title:'Full Khatm-e-Quran',desc:'Complete Quran (30 Para)',price:499,paraCount:30,hot:true},
 {id:'yaseen',title:'Surah Yaseen',desc:'One recitation of Surah Yaseen',price:29,paraCount:0},
 {id:'rahman',title:'Surah Rahman',desc:'One recitation of Surah Rahman',price:19,paraCount:0},
 {id:'durood',title:'Durood-e-Taj',desc:'One recitation of Durood-e-Taj',price:19,paraCount:0},
 {id:'digital_mulk',title:'Surah Al-Mulk — Premium Booklet',desc:'Verse-by-verse PDF companion: Arabic, English, Urdu & Hinglish',price:49,paraCount:0,digital:true,file:'DIGITAL_FILE_MULK',filename:'ILMORA_Surah_Al_Mulk.pdf'},
 {id:'digital_yaseen',title:'Surah Yaseen — Premium Booklet',desc:'Verse-by-verse PDF companion: Arabic, English, Urdu & Hinglish',price:49,paraCount:0,digital:true,file:'DIGITAL_FILE_YASEEN',filename:'ILMORA_Surah_Yaseen.pdf'}
];
function appFee(price){return price<100?10:(price<=300?20:30)}
function renderPackages(){$('pkgList').innerHTML=packages.filter(p=>!p.digital).map(p=>`<div class="pkg ${p.hot?'hot':''}">${p.hot?'<span class="badge">Popular</span>':''}<b>${p.title}</b><small>${p.desc}</small><div class="price">₹${p.price} <span>/ order</span></div><button onclick="openOrderForm('${p.id}')">Order Now</button></div>`).join('')}
function renderDigitalStore(){$('digitalList').innerHTML=packages.filter(p=>p.digital).map(p=>`<button class="tile" style="text-align:left;align-items:flex-start" onclick="openOrderForm('${p.id}')"><div class="ico">📘</div><b>${p.title}</b><small>${p.desc}</small><div class="price" style="margin-top:6px">₹${p.price} <span>/ PDF</span></div></button>`).join('')}
function renderDigitalOrders(){const el=$('digitalOrderHistory');if(!el)return;const digitalOrders=state.orders.filter(o=>o.digitalFile);if(!digitalOrders.length){el.innerHTML='<div class="empty">No digital purchases yet.</div>';return}el.innerHTML=digitalOrders.slice().reverse().map(o=>`<div class="orow"><span>${o.pkg}<br><small style="color:var(--muted)">${o.id} • ${new Date(o.date).toLocaleDateString()}</small></span><button class="pill" onclick="downloadDigitalFile('${o.id}')">⬇ Download</button></div>`).join('')}
function downloadDigitalFile(orderId){const o=state.orders.find(x=>x.id===orderId);if(!o||!o.digitalFile){toast('File not found');return}const a=document.createElement('a');a.href=window[o.digitalFile];a.download=o.digitalFilename||'Ilmora.pdf';document.body.appendChild(a);a.click();document.body.removeChild(a)}
function openOrderForm(pkgId,presetPara){const p=packages.find(x=>x.id===pkgId);if(!p)return;
  let paraPickHtml='';
  if(p.id==='para1'){
    const avail=availableParas();
    if(!avail.length){toast('All 30 Para are already sponsored — Alhamdulillah!');return}
    const choice=presetPara&&avail.includes(presetPara)?presetPara:avail[0];
    paraPickHtml=`<label style="font-size:11px;color:var(--muted);display:block;margin-bottom:6px">Choose Para to sponsor</label><select id="ordPara" class="field">${avail.map(n=>`<option value="${n}" ${n===choice?'selected':''}>Para ${n} — ${studentForPara(n)?getStudentName(studentForPara(n)):'Student'}</option>`).join('')}</select>`;
  }
  const footerNote=p.digital?`Your PDF will unlock for download right after you submit your payment reference.`:`Most of this amount goes directly to the madrasa children as sadaqah; a small share (₹${appFee(p.price)}) supports the Ilmora app.`;
  openModal((p.digital?'Order — ':'Order — ')+p.title,`<div class="orow"><span>Package</span><b>${p.title}</b></div><div class="orow"><span>Amount${p.digital?'':' (Sadaqah)'}</span><b>₹${p.price}</b></div>${paraPickHtml}<input id="ordName" class="field" placeholder="Your name"><input id="ordPhone" class="field" placeholder="Mobile number" inputmode="tel">${p.digital?'':'<input id="ordNiyat" class="field" placeholder="Niyat / dedication (optional)">'}<button class="counter-btn" onclick="proceedToPayment('${p.id}')">Proceed to Pay ₹${p.price} →</button><p style="color:var(--muted);font-size:10px;margin-top:10px;text-align:center">${footerNote}</p>`)}
function proceedToPayment(pkgId){const p=packages.find(x=>x.id===pkgId);const name=$('ordName').value.trim(),phone=$('ordPhone').value.trim(),niyat=$('ordNiyat')?$('ordNiyat').value.trim():'';if(!name||!phone){toast('Name and mobile number are required');return}
  let assignedParas=[];
  if(p.id==='para1'){const sel=$('ordPara');assignedParas=sel?[Number(sel.value)]:[];}
  else if(p.paraCount>0){assignedParas=availableParas().slice(0,p.paraCount);}
  if(p.paraCount>0&&!assignedParas.length){toast('Not enough Para available right now — please choose a smaller package');return}
  state.pendingOrder={pkgId,name,phone,niyat,assignedParas};
  const upiLink=`upi://pay?pa=${UPI_VPA}&pn=Ilmora%20Madrasa%20Isal-e-Sawab&am=${p.price}&cu=INR&tn=${encodeURIComponent(p.title)}`;
  openModal('Complete Your Payment',`<div class="orow"><span>Package</span><b>${p.title}</b></div><div class="orow"><span>Amount</span><b>₹${p.price}</b></div>${assignedParas.length?`<div class="orow"><span>Para</span><b>${assignedParas.join(', ')}</b></div>`:''}<a href="${upiLink}" id="upiPayLink" onclick="onUpiPayTapped()" style="display:block;text-align:center;text-decoration:none;margin:18px 0"><button class="counter-btn" style="font-size:24px;padding:28px;width:100%;box-shadow:0 12px 30px rgba(15,118,110,.35)">💳<br>Pay ₹${p.price} via UPI</button></a><p style="color:var(--muted);font-size:11px;text-align:center;margin-bottom:14px">Tap above to open GPay / PhonePe / Paytm and complete the payment.</p><div id="confirmPaySection" style="display:none"><label style="font-size:11px;color:var(--muted);display:block;margin-bottom:6px">Enter the 12-digit UPI Transaction / Reference Number (UTR) from your payment app</label><input id="ordUtr" class="field" maxlength="12" inputmode="numeric" placeholder="e.g. 987654321012"><button class="counter-btn" style="background:linear-gradient(135deg,#16a34a,#15803d)" onclick="finalizeOrder()">✅ Submit for Verification</button><p style="color:var(--muted);font-size:10px;margin-top:8px;text-align:center">Your Para will be reserved once submitted, and confirmed once we verify the UTR against our bank statement.</p></div><button class="pill" style="margin-top:10px;width:100%" onclick="closeModal()">Cancel</button>`);
  window.__upiTapped=false;
}
function onUpiPayTapped(){
  window.__upiTapped=true;
  const reveal=()=>{const sec=$('confirmPaySection');if(sec)sec.style.display='block'};
  // primary signal: user leaves this tab/app (to open UPI app) and comes back
  const onVis=()=>{if(document.visibilityState==='visible'&&window.__upiTapped){reveal();document.removeEventListener('visibilitychange',onVis)}};
  document.addEventListener('visibilitychange',onVis);
  // fallback in case visibility change doesn't fire on some browsers
  setTimeout(reveal,6000);
}
function finalizeOrder(){const pending=state.pendingOrder;if(!pending){closeModal();return}const p=packages.find(x=>x.id===pending.pkgId);const{name,phone,niyat,assignedParas}=pending;
  const utr=$('ordUtr')?$('ordUtr').value.trim():'';
  if(!/^\d{4,12}$/.test(utr)){toast('Please enter a valid UTR / Reference Number from your payment app');return}
  if(p.paraCount>0){const stillAvail=availableParas();const invalid=assignedParas.filter(n=>!stillAvail.includes(n));if(invalid.length){toast('Sorry, Para '+invalid.join(', ')+' got booked by someone else — please choose again');closeModal();state.pendingOrder=null;return}}
  const fee=appFee(p.price);const order={id:'ORD'+Date.now(),pkg:p.title,price:p.price,fee,madrasaShare:p.price-fee,name,phone,niyat,utr,paras:assignedParas,status:p.digital?'Paid':'Payment Pending — Verifying UTR',date:new Date().toISOString()};if(p.digital){order.digitalFile=p.file;order.digitalFilename=p.filename}state.orders.push(order);localStorage.setItem('ilmora_orders',JSON.stringify(state.orders));
  if(assignedParas.length){bookParas(assignedParas,name,order.id);renderParaGrid();renderStudents()}
  if(window.__fsAdd){
    window.__fsAdd(order).then(()=>toast('✅ Submitted — awaiting UTR verification')).catch(err=>{console.error('Cloud sync failed',err);toast('⚠️ Saved on device only — cloud sync failed')});
  }else{
    console.warn('Firebase not ready yet');
    toast('⚠️ Saved on device only — cloud not connected');
  }
  state.pendingOrder=null;
  const studentNames=[...new Set(assignedParas.map(n=>studentForPara(n)?getStudentName(studentForPara(n)):null).filter(Boolean))];
  const paraLine=assignedParas.length?`<div class="orow"><span>Para Assigned</span><b>${assignedParas.join(', ')}</b></div><div class="orow"><span>Reciting Student${studentNames.length>1?'s':''}</span><b>${studentNames.join(', ')||'—'}</b></div>`:'';
  if(p.digital){
    openModal('Payment Received — Download Ready ✅',`<div class="orow"><span>Order ID</span><b>${order.id}</b></div><div class="orow"><span>Package</span><b>${p.title}</b></div><div class="orow"><span>Amount</span><b>₹${p.price}</b></div><div class="orow"><span>UTR Submitted</span><b>${utr}</b></div><button class="counter-btn" style="background:linear-gradient(135deg,#16a34a,#15803d);margin-top:14px" onclick="downloadDigitalFile('${order.id}')">⬇ Download Your PDF</button><p style="color:var(--muted);font-size:10px;margin-top:10px;text-align:center">This PDF will also stay saved under Digital Store → My Digital Purchases.</p><button class="pill" style="width:100%;margin-top:8px" onclick="closeModal();renderDigitalOrders()">Done</button>`);
    toast('Purchased: '+order.id);
    return;
  }
  openModal('Submitted — Verification Pending ⏳',`<div class="orow"><span>Order ID</span><b>${order.id}</b></div><div class="orow"><span>Package</span><b>${p.title}</b></div><div class="orow"><span>Amount</span><b>₹${p.price}</b></div><div class="orow"><span>UTR Submitted</span><b>${utr}</b></div>${paraLine}<p style="color:var(--muted);font-size:11px;line-height:1.6;margin-top:10px">Your Para is reserved. Once we verify your UTR against our bank statement, your order will be marked as Paid and the children will begin the recitation with your dedication in mind, In Sha Allah.</p><button class="pill" style="width:100%" onclick="closeModal();renderOrders()">Done</button>`);toast('Submitted for verification: '+order.id)}
function renderOrders(){const sadaqahOrders=state.orders.filter(o=>!o.digitalFile);if(!sadaqahOrders.length){$('orderHistory').innerHTML='<div class="empty">No orders yet.</div>'}else{$('orderHistory').innerHTML=sadaqahOrders.slice().reverse().map(o=>`<div class="orow"><span>${o.pkg}<br><small style="color:var(--muted)">${o.id} • ${new Date(o.date).toLocaleDateString()}</small></span><div style="text-align:right"><b>₹${o.price}</b><br><button class="pill" style="padding:4px 10px;font-size:10px;margin-top:4px" onclick="showCertificate('${o.id}')">Certificate</button></div></div>`).join('')}
  renderLeaderboard();
}
function renderLeaderboard(){const el=$('leaderboard');if(!el)return;const sadaqahOrders=state.orders.filter(o=>!o.digitalFile);if(!sadaqahOrders.length)return;const totals={};sadaqahOrders.forEach(o=>{const key=o.name||'Anonymous';totals[key]=(totals[key]||0)+o.price});const top=Object.entries(totals).sort((a,b)=>b[1]-a[1]).slice(0,5);el.innerHTML=top.map(([name,amt],i)=>`<div class="orow"><span>${['🥇','🥈','🥉','🏅','🏅'][i]} ${name}</span><b>₹${amt}</b></div>`).join('')}
function showCertificate(orderId){const o=state.orders.find(x=>x.id===orderId);if(!o)return;const dateStr=new Date(o.date).toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'});openModal('Sponsorship Certificate',`<div style="background:linear-gradient(135deg,#fff,#fff7ea);border:2px solid #e0ad42;border-radius:16px;padding:24px;text-align:center"><div style="font-size:11px;letter-spacing:2px;color:var(--gold);font-weight:800">CERTIFICATE OF ISAL-E-SAWAB</div><div style="font-size:22px;margin:14px 0 4px;font-weight:900;color:var(--ink)">${o.name}</div><div style="font-size:12px;color:var(--muted);margin-bottom:14px">has sponsored</div><div style="font-size:17px;font-weight:800;color:var(--teal)">${o.pkg}</div>${o.paras&&o.paras.length?`<div style="font-size:11px;color:var(--muted);margin-top:4px">Para ${o.paras.join(', ')}</div>`:''}<div style="font-size:11px;color:var(--muted);margin-top:14px">on ${dateStr} • Order ${o.id}</div><div style="font-size:10px;color:var(--muted);margin-top:10px;font-style:italic">"Whoever guides someone to a good deed gets a reward like the one who did it." — Sahih Muslim</div></div><div class="rowbtn"><button class="pill" onclick="window.print()">🖨 Print / Save PDF</button><button class="pill" onclick="closeModal()">Close</button></div>`)}
document.querySelectorAll('.nav').forEach(n=>n.onclick=()=>showScreen(n.dataset.screen));
function parseTime(s){const [h,m]=s.split(':').map(Number);const d=new Date();d.setHours(h,m,0,0);return d}
function updateClock(){const now=new Date();$('today').textContent=now.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'});checkAdhan(now);if(!state.timings)return;let next=null;for(const n of prayers){const d=parseTime(state.timings[n]);if(d>now){next={n,d};break}}if(!next){next={n:'Fajr',d:parseTime(state.timings.Fajr)};next.d.setDate(next.d.getDate()+1)}let sec=Math.max(0,Math.floor((next.d-now)/1000));const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;const c=`${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m ${String(s).padStart(2,'0')}s`;$('nextPrayer').textContent=next.n;$('countdown').textContent='in '+c;$('bigNext').textContent=next.n+' • '+state.timings[next.n];renderPrayerList(next.n)}
function renderPrayerList(next){const rows=prayers.map(n=>`<div class="timing ${n===next?'nextrow':''}"><strong>${n}</strong><span class="t">${state.timings[n]}</span></div>`).join('');$('timings').innerHTML=rows;$('homePrayers').innerHTML=rows}
async function getLocation(){if(!navigator.geolocation)return loadPrayer(25.5941,85.1376,'Patna (approx.)');navigator.geolocation.getCurrentPosition(p=>loadPrayer(p.coords.latitude,p.coords.longitude,'Your location'),()=>loadPrayer(25.5941,85.1376,'Patna (approx.)'))}
async function loadPrayer(lat,lon,label){$('location').textContent='⌖ '+label;try{const r=await fetch(`https://api.aladhan.com/v1/timings?latitude=${lat}&longitude=${lon}&method=1`);if(!r.ok)throw Error();const j=await r.json();state.timings=j.data.timings;$('method').textContent='Muslim World League • timings may vary by local authority';updateClock()}catch(e){$('homePrayers').innerHTML='<div class="empty">Prayer timings unavailable. Check your internet connection.</div>';$('timings').innerHTML='<div class="empty">Prayer timings unavailable.</div>'}}
async function loadSurahs(){if(state.surahs.length)return;try{const r=await fetch('https://api.alquran.cloud/v1/surah');const j=await r.json();state.surahs=j.data;renderSurahs(state.surahs)}catch(e){$('surahList').innerHTML='<div class="empty">Could not load Quran. Check your internet connection.</div>'}}
function renderSurahs(arr){$('surahList').innerHTML=arr.map(s=>`<button class="surah" onclick="openSurah(${s.number})"><span class="num">${s.number}</span><span><b>${s.englishName}</b><small>${s.englishNameTranslation} • ${s.numberOfAyahs} Ayahs</small></span><span class="ar">${s.name}</span></button>`).join('')}
$('surahSearch').oninput=e=>{const q=e.target.value.toLowerCase();renderSurahs(state.surahs.filter(s=>s.englishName.toLowerCase().includes(q)||s.englishNameTranslation.toLowerCase().includes(q)||String(s.number)===q))};$('translationSelect').onchange=()=>{if($('reader').style.display!=='none'&&state.lastRead)openSurah(state.lastRead.surah)}
async function openSurah(n){$('quranList').style.display='none';$('reader').style.display='block';$('readerContent').innerHTML='<div class="empty">Loading Surah with translation…</div>';try{const edition=$('translationSelect')?.value||'en.sahih';const [ar,trj]=await Promise.all([fetch(`https://api.alquran.cloud/v1/surah/${n}/quran-uthmani`).then(r=>r.json()),fetch(`https://api.alquran.cloud/v1/surah/${n}/${edition}`).then(r=>r.json())]);const info=ar.data,tr=trj.data;state.lastRead={surah:n,ayah:1,at:Date.now()};save();$('readerContent').innerHTML=`<div class="reader-head"><button class="back" onclick="closeReader()">‹</button><div class="reader-title"><b>${info.englishName}</b><small>${info.englishNameTranslation} • ${info.numberOfAyahs} Ayahs</small></div><button class="action" onclick="playAyah(${info.ayahs[0].number},'${info.englishName.replace(/'/g,'')}')">▶ Play</button></div>`+info.ayahs.map((a,i)=>`<article class="ayah"><div class="ayah-no">AYAH ${a.numberInSurah}</div><div class="ayah-ar">${a.text}</div><div class="ayah-tr">${tr[i]?.text||''}</div><div class="ayah-actions"><button class="tiny" onclick="playAyah(${a.number},'${info.englishName} ${a.numberInSurah}')">▶ Listen</button><button class="tiny" onclick='toggleBookmark(${n},${a.numberInSurah})'>☆ ${state.bookmarks.includes(n+':'+a.numberInSurah)?'Saved':'Save'}</button><button class="tiny" onclick='shareText(${JSON.stringify(a.text)})'>Share</button></div></article>`).join('')}catch(e){$('readerContent').innerHTML='<div class="empty">Unable to load this Surah right now.</div>'}}
function closeReader(){$('reader').style.display='none';$('quranList').style.display='block';if(state.audio){state.audio.pause();state.audio=null;$('mini').classList.remove('show')}}
function toggleBookmark(s,a){const k=s+':'+a;state.bookmarks.includes(k)?state.bookmarks=state.bookmarks.filter(x=>x!==k):state.bookmarks.push(k);save();toast(state.bookmarks.includes(k)?'Ayah bookmarked':'Bookmark removed')}
function playAyah(globalNo,title='Quran Audio'){if(state.audio)state.audio.pause();const a=new Audio(`https://cdn.islamic.network/quran/audio/128/ar.alafasy/${globalNo}.mp3`);state.audio=a;$('track').textContent=title;$('mini').classList.add('show');$('play').onclick=()=>a.paused?a.play():a.pause();$('closeAudio').onclick=()=>{a.pause();$('mini').classList.remove('show')};a.onplay=()=>{$('play').textContent='Ⅱ'};a.onpause=()=>{$('play').textContent='▶'};a.onended=()=>{$('mini').classList.remove('show');toast('Ayah finished ✓')};a.play().catch(()=>toast('Tap play to start audio'))}
function shareText(text){if(navigator.share)navigator.share({title:'Ilmora',text}).catch(()=>{});else navigator.clipboard?.writeText(text).then(()=>toast('Copied to clipboard'))}
$('shareVerse').onclick=()=>shareText(($('verseEn').textContent||'Indeed, with hardship comes ease.')+' — '+$('verseRef').textContent);
$('tasbeehBtn').onclick=()=>{state.tasbeeh++;save();toast('Tasbeeh: '+state.tasbeeh)};

const hadithData=[
 {ar:'إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ',en:'Actions are judged by intentions.',hi:'कर्मों का दारोमदार नीयतों पर है।',ref:'Sahih al-Bukhari 1',topic:'intentions'},
 {ar:'مَنْ لَا يَرْحَمُ لَا يُرْحَمُ',en:'Whoever does not show mercy will not be shown mercy.',hi:'जो दया नहीं करता, उस पर दया नहीं की जाती।',ref:'Sahih al-Bukhari 7376',topic:'mercy'},
 {ar:'خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ',en:'The best of you are those who learn the Quran and teach it.',hi:'तुम में सबसे बेहतर वह है जो कुरआन सीखे और सिखाए।',ref:'Sahih al-Bukhari 5027',topic:'quran learning'},
 {ar:'الطُّهُورُ شَطْرُ الإِيمَانِ',en:'Purification is half of faith.',hi:'पवित्रता ईमान का आधा हिस्सा है।',ref:'Sahih Muslim 223',topic:'purification'},
 {ar:'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ',en:'Whoever believes in Allah and the Last Day should speak good or remain silent.',hi:'जो अल्लाह और आख़िरत पर ईमान रखता है, उसे अच्छी बात कहनी चाहिए या चुप रहना चाहिए।',ref:'Sahih al-Bukhari 6018',topic:'speech manners'},
 {ar:'لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ',en:'The strong one is not the one who overcomes people by his strength, but the one who controls himself while angry.',hi:'ताक़तवर वह नहीं जो कुश्ती में जीते, बल्कि वह है जो ग़ुस्से के वक़्त ख़ुद पर काबू रखे।',ref:'Sahih al-Bukhari 6114',topic:'anger and patience'},
 {ar:'لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ',en:'None of you truly believes until he loves for his brother what he loves for himself.',hi:'तुम में से कोई तब तक पूरा मोमिन नहीं होता जब तक अपने भाई के लिए वही पसंद न करे जो अपने लिए पसंद करता है।',ref:'Sahih al-Bukhari 13',topic:'brotherhood'},
 {ar:'الْحَيَاءُ مِنَ الْإِيمَانِ',en:'Modesty is part of faith.',hi:'हया ईमान का हिस्सा है।',ref:'Sahih al-Bukhari 9',topic:'modesty'},
 {ar:'إِنَّ مِنْ خِيَارِكُمْ أَحْسَنَكُمْ أَخْلَاقًا',en:'The best among you are those with the best manners and character.',hi:'तुम में सबसे बेहतर वह है जिसका अख़लाक़ सबसे अच्छा हो।',ref:'Sahih al-Bukhari 3559',topic:'good character'},
 {ar:'تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ',en:'Smiling at your brother is charity.',hi:'अपने भाई के सामने मुस्कुराना भी सदक़ा है।',ref:'Jami at-Tirmidhi 1956',topic:'kindness'},
 {ar:'طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ',en:'Seeking knowledge is an obligation upon every Muslim.',hi:'इल्म हासिल करना हर मुसलमान पर फ़र्ज़ है।',ref:'Sunan Ibn Majah 224',topic:'seeking knowledge'},
 {ar:'الدَّالُّ عَلَى الْخَيْرِ كَفَاعِلِهِ',en:'Whoever guides someone to a good deed gets a reward like the one who did it.',hi:'जो किसी नेकी की राह दिखाए, उसे उसी के बराबर सवाब मिलता है।',ref:'Sahih Muslim 1893',topic:'guidance'},
 {ar:'أَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ',en:'The most beloved deeds to Allah are those done consistently, even if small.',hi:'अल्लाह को सबसे ज़्यादा पसंद वह अमल है जो हमेशा किया जाए, भले ही थोड़ा हो।',ref:'Sahih al-Bukhari 6465',topic:'consistency'},
 {ar:'الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ',en:'A good word is a form of charity.',hi:'अच्छी बात कहना भी सदक़ा है।',ref:'Sahih al-Bukhari 2989',topic:'kind words'},
 {ar:'إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ',en:'Allah does not look at your appearance or wealth, but looks at your hearts and deeds.',hi:'अल्लाह तुम्हारी शक्ल और माल को नहीं देखता, बल्कि तुम्हारे दिलों और आमाल को देखता है।',ref:'Sahih Muslim 2564',topic:'sincerity'},
 {ar:'لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ',en:'None of you will enter Paradise until you truly believe, and you will not truly believe until you love one another.',hi:'तुम जन्नत में तब तक नहीं जाओगे जब तक ईमान न लाओ, और ईमान तब तक पूरा नहीं जब तक आपस में मोहब्बत न रखो।',ref:'Sahih Muslim 54',topic:'love and unity'},
 {ar:'مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ',en:'Whoever relieves a believer\u2019s hardship, Allah will relieve his hardship on the Day of Judgement.',hi:'जो किसी मोमिन की मुसीबत दूर करे, अल्लाह क़यामत के दिन उसकी मुसीबत दूर करेगा।',ref:'Sahih Muslim 2699',topic:'helping others'},
 {ar:'الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ',en:'A Muslim is the brother of another Muslim; he neither wrongs him nor abandons him.',hi:'एक मुसलमान दूसरे मुसलमान का भाई है, न उस पर ज़ुल्म करे न उसे तन्हा छोड़े।',ref:'Sahih al-Bukhari 2442',topic:'brotherhood'},
 {ar:'مَنْ لَا يَشْكُرِ النَّاسَ لَا يَشْكُرِ اللَّهَ',en:'Whoever does not thank people has not thanked Allah.',hi:'जो लोगों का शुक्रिया अदा नहीं करता, वह अल्लाह का भी शुक्रिया अदा नहीं करता।',ref:'Jami at-Tirmidhi 1954',topic:'gratitude'},
 {ar:'لَيْسَ مِنَّا مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيُوَقِّرْ كَبِيرَنَا',en:'He is not one of us who does not show mercy to our young and respect to our elders.',hi:'वह हम में से नहीं जो हमारे छोटों पर रहम न करे और बड़ों की इज़्ज़त न करे।',ref:'Jami at-Tirmidhi 1919',topic:'respect for elders'},
 {ar:'مَنْ صَمَتَ نَجَا',en:'Whoever remains silent (from harmful speech) is saved.',hi:'जो चुप रहे, वह बच गया।',ref:'Jami at-Tirmidhi 2501',topic:'guarding the tongue'},
 {ar:'الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ',en:'The strong believer is better and more beloved to Allah than the weak believer.',hi:'ताक़तवर मोमिन कमज़ोर मोमिन से बेहतर और अल्लाह को ज़्यादा प्यारा है।',ref:'Sahih Muslim 2664',topic:'strength in faith'},
 {ar:'مَنْ حَسُنَ إِسْلَامُ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ',en:'Part of the perfection of one\u2019s Islam is leaving that which does not concern him.',hi:'इंसान के अच्छे इस्लाम की निशानी है कि वह उन बातों को छोड़ दे जिनसे उसका कोई सरोकार नहीं।',ref:'Jami at-Tirmidhi 2317',topic:'mindfulness'},
 {ar:'الدُّنْيَا مَتَاعٌ وَخَيْرُ مَتَاعِ الدُّنْيَا الْمَرْأَةُ الصَّالِحَةُ',en:'The world is a provision, and the best provision of the world is a righteous companion.',hi:'दुनिया एक सामान है, और दुनिया के सामान में सबसे अच्छा एक नेक साथी है।',ref:'Sahih Muslim 1467',topic:'righteous companionship'},
 {ar:'إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ',en:'Allah is gentle and loves gentleness in all matters.',hi:'अल्लाह नरमी वाला है और हर काम में नरमी को पसंद करता है।',ref:'Sahih al-Bukhari 6927',topic:'gentleness'},
 {ar:'خَيْرُ النَّاسِ أَنْفَعُهُمْ لِلنَّاسِ',en:'The best of people are those most beneficial to others.',hi:'लोगों में सबसे बेहतर वह है जो लोगों के लिए सबसे ज़्यादा फ़ायदेमंद हो।',ref:'Al-Mu\u2019jam al-Awsat, commonly cited hasan hadith',topic:'benefiting others'},
 {ar:'مَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ',en:'Whoever conceals the faults of a Muslim, Allah will conceal his faults in this world and the Hereafter.',hi:'जो किसी मुसलमान की ग़लती छुपाए, अल्लाह दुनिया और आख़िरत दोनों में उसकी ग़लती छुपाएगा।',ref:'Sahih Muslim 2699',topic:'covering faults'},
 {ar:'الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَٰنُ',en:'Those who are merciful will be shown mercy by the Most Merciful.',hi:'जो लोग रहम करते हैं, अल्लाह उन पर रहम करता है।',ref:'Jami at-Tirmidhi 1924',topic:'mercy'},
 {ar:'كُلُّ ابْنِ آدَمَ خَطَّاءٌ وَخَيْرُ الْخَطَّائِينَ التَّوَّابُونَ',en:'Every son of Adam sins, and the best of sinners are those who repent.',hi:'हर इंसान से ग़लती होती है, और सबसे बेहतर ग़लती करने वाले वे हैं जो तौबा करते हैं।',ref:'Jami at-Tirmidhi 2499',topic:'repentance'},
 {ar:'مَنْ لَمْ يَشْكُرِ الْقَلِيلَ لَمْ يَشْكُرِ الْكَثِيرَ',en:'Whoever does not thank Allah for small blessings will not thank Him for abundant ones.',hi:'जो छोटी नेमतों का शुक्र अदा नहीं करता, वह बड़ी नेमतों का भी शुक्र अदा नहीं कर पाएगा।',ref:'Musnad Ahmad, commonly cited',topic:'gratitude'},
 {ar:'إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَمَلُهُ إِلَّا مِنْ ثَلَاثٍ',en:'When a person dies, his deeds end except for three: ongoing charity, beneficial knowledge, or a righteous child who prays for him.',hi:'जब इंसान मरता है तो उसके अमल ख़त्म हो जाते हैं सिवाय तीन के: जारी सदक़ा, फ़ायदेमंद इल्म, या नेक औलाद जो उसके लिए दुआ करे।',ref:'Sahih Muslim 1631',topic:'ongoing charity'},
 {ar:'مَنْ بَنَى لِلَّهِ مَسْجِدًا بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ',en:'Whoever builds a mosque for Allah, Allah will build for him a house in Paradise.',hi:'जो अल्लाह के लिए मस्जिद बनाए, अल्लाह उसके लिए जन्नत में घर बनाएगा।',ref:'Sahih al-Bukhari 450',topic:'building mosques'},
 {ar:'الْجَنَّةُ تَحْتَ ظِلَالِ السُّيُوفِ',en:'Paradise is beneath the shade of swords — referring to striving and sacrifice in the path of good.',hi:'जन्नत तलवारों के साये तले है — यानी नेकी की राह में मेहनत और क़ुर्बानी से।',ref:'Sahih al-Bukhari 2818',topic:'striving'},
 {ar:'مَنْ عَادَ مَرِيضًا نَادَى مُنَادٍ مِنَ السَّمَاءِ طِبْتَ وَطَابَ مَمْشَاكَ',en:'Whoever visits a sick person, a caller from the sky announces: You are good, and your path is good.',hi:'जो किसी बीमार से मिलने जाए, आसमान से आवाज़ आती है: तू अच्छा है और तेरा रास्ता अच्छा है।',ref:'Jami at-Tirmidhi 2008',topic:'visiting the sick'},
 {ar:'إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ',en:'Allah has ninety-nine names; whoever memorises and reflects on them will enter Paradise.',hi:'अल्लाह के निन्यानवे नाम हैं, जो उन्हें याद रखे और समझे, वह जन्नत में दाख़िल होगा।',ref:'Sahih al-Bukhari 2736',topic:'names of Allah'},
 {ar:'مَنْ قَالَ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ',en:'Whoever says "Subhan Allahi wa bihamdihi" a hundred times a day, his sins are wiped away.',hi:'जो दिन में सौ बार "सुबहान अल्लाहि व बिहम्दिही" कहे, उसके गुनाह माफ़ कर दिए जाते हैं।',ref:'Sahih al-Bukhari 6405',topic:'remembrance of Allah'}
];
function renderHadith(q=''){const a=hadithData.filter(h=>!q||[h.en,h.hi,h.topic,h.ref].join(' ').toLowerCase().includes(q.toLowerCase()));$('hadithList').innerHTML=a.map(h=>`<article class="card" style="margin:9px 0"><div class="ayah-ar">${h.ar}</div><div class="translation"><b>English:</b> ${h.en}</div><div class="translation"><b>हिन्दी:</b> ${h.hi}</div><div class="ref">${h.ref}</div><button class="pill" onclick="shareText(${JSON.stringify(h.en+' — '+h.ref)})">↗ Share</button></article>`).join('')||'<div class="empty">No hadith found.</div>'}
$('hadithSearch').oninput=e=>renderHadith(e.target.value);
$('qiblaBtn').onclick=openQibla;
$('duaBtn').onclick=openDuas;
$('openSaved').onclick=()=>{try{showScreen('quran');if(state.lastRead)openSurah(state.lastRead.surah)}catch(e){console.error('openSaved failed',e);toast('⚠️ Could not open: '+e.message)}};
$('reminders').onclick=()=>toast('Prayer reminder preference saved locally');
$('about').onclick=()=>toast('Ilmora • focused worship companion');
async function verse(){try{const n=(Math.floor(Date.now()/86400000)%6236)+1;const j=await (await fetch(`https://api.alquran.cloud/v1/ayah/${n}/editions/quran-uthmani,en.sahih`)).json();const ar=j.data.find(x=>x.edition.identifier==='quran-uthmani'),en=j.data.find(x=>x.edition.identifier==='en.sahih');if(ar){$('verseAr').textContent=ar.text;$('verseRef').textContent=ar.surah.englishName+' • '+ar.surah.number+':'+ar.numberInSurah}if(en)$('verseEn').textContent=en.text}catch(e){$('verseEn').textContent='Indeed, with hardship comes ease.';$('verseRef').textContent="Qur'an 94:5"}}
applyTheme();updateStats();setInterval(updateClock,1000);updateClock();getLocation();verse();
